provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  default     = null
  description = "Name of the state bucket. Defaults to reports-tfstate-<account id>, which is globally unique."
}

variable "state_access_principal_arns" {
  type        = list(string)
  description = "IAM role/user ARNs allowed to read and write state (and use the KMS key). Everyone else is denied by the bucket policy."
}
EOF
cat > main.tf <<'EOF'
data "aws_caller_identity" "current" {}

locals {
  bucket_name = coalesce(var.state_bucket_name, "reports-tfstate-${data.aws_caller_identity.current.account_id}")
}

# The state holds the uploader's IAM secret access key in plaintext, so it is
# encrypted with a customer-managed key and access is limited to named principals.
resource "aws_kms_key" "state" {
  description             = "Encrypts Terraform state for the reports configuration"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "state" {
  name          = "alias/reports-tfstate"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyEveryoneExceptStateUsers"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "ArnNotLike"
      variable = "aws:PrincipalArn"
      values   = var.state_access_principal_arns
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  value = aws_kms_key.state.arn
}
EOF
cat > terraform.tfvars.example <<'EOF'
state_access_principal_arns = [
  "arn:aws:iam::123456789012:role/terraform-reports",
  "arn:aws:iam::123456789012:user/example-admin",
]
EOF
cd ..
cat > backend.tf <<'EOF'
# The bucket is created by bootstrap/. Its name is passed at init time:
#   terraform init -backend-config="bucket=<state_bucket output>"
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
    # kms_key_id is optional: the bucket default already encrypts with the CMK.
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfvars
!*.tfvars.example
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

State is stored in S3 (versioned, KMS-encrypted, locked with S3 native lockfiles), so anyone
with access can run `plan` and `apply`. The state contains the uploader's secret access key in
plaintext, so access to the bucket is restricted to an explicit list of IAM principals.

## One-time bootstrap (one person, once)

`bootstrap/` creates the state bucket and KMS key. Its own state is small, holds no secrets, and
stays local; keep `bootstrap/terraform.tfstate` safe (or commit nothing from it).

```sh
cd bootstrap
cp terraform.tfvars.example terraform.tfvars   # list the IAM role/user ARNs of everyone who runs Terraform
terraform init
terraform apply
terraform output state_bucket
```

Include the bootstrap operator's own ARN in `state_access_principal_arns`, otherwise they are
locked out of the bucket by the policy.

## Migrating the existing local state (once)

From the repo root, on the machine that holds the current `terraform.tfstate`:

```sh
terraform init -migrate-state -backend-config="bucket=<state_bucket output>"
terraform plan   # should show no changes
```

Then delete the local `terraform.tfstate*` files (they contain the secret key).

## Everyday workflow

```sh
terraform init -backend-config="bucket=<state_bucket output>"
terraform plan
terraform apply
```

Locking uses an S3 lockfile (`terraform.tfstate.tflock`), so no DynamoDB table is needed.
Requires Terraform >= 1.10. Users need `s3:GetObject`, `s3:PutObject`, `s3:DeleteObject` and
`s3:ListBucket` on the bucket and `kms:Encrypt`, `kms:Decrypt`, `kms:GenerateDataKey` on the key
through their own IAM policies, in addition to being listed in the bucket policy.
EOF
which terraform && (cd bootstrap && terraform init -backend=false >/dev/null && terraform validate; cd .. && terraform init -backend=false >/dev/null && terraform validate)

